[data-slot='toggle-group']>[data-slot='toggle']:last-child{border-radius:8px 9999px 9999px 8px!important}
[data-slot='toggle-group']>[data-slot='toggle'][data-pressed]{border-radius:9999px!important;background:var(--primary)!important;color:var(--primary-foreground)!important}
[data-slot='toggle-group']>[data-slot='toggle']::before{display:none!important}
[data-slot='group']{gap:2px}
[data-slot='group']>[data-slot='button']{border-radius:8px!important}
[data-slot='group']>[data-slot='button']:first-child{border-radius:9999px 8px 8px 9999px!important}
[data-slot='group']>[data-slot='button']:last-child{border-radius:8px 9999px 9999px 8px!important}
@media (prefers-reduced-motion:reduce){[data-thread-details-card] span[class*='h-[3px]']>span{animation:none}}

/* shelves (working/snoozed/settled) onderaan zoals standaard T3 */
[data-slot='sidebar-inner'] [data-slot='scroll-area-viewport']:has(li:is([data-testid='sidebar-working-header'],[data-testid='sidebar-snoozed-header'],[data-testid='sidebar-settled-header'])){display:flex!important;flex-direction:column!important}
[data-slot='sidebar-inner'] [data-slot='scroll-area-viewport'] :has(ul > li:is([data-testid='sidebar-working-header'],[data-testid='sidebar-snoozed-header'],[data-testid='sidebar-settled-header'])){display:flex!important;flex-direction:column!important;flex:1 0 auto!important}
[data-slot='sidebar-inner'] [data-slot='scroll-area-viewport'] ul:has(> li:is([data-testid='sidebar-working-header'],[data-testid='sidebar-snoozed-header'],[data-testid='sidebar-settled-header'])){flex:1 0 auto!important}
[data-slot='sidebar-inner'] [data-slot='scroll-area-viewport'] ul > li:is([data-testid='sidebar-working-header'],[data-testid='sidebar-snoozed-header'],[data-testid='sidebar-settled-header']):not(li:is([data-testid='sidebar-working-header'],[data-testid='sidebar-snoozed-header']) ~ li){margin-top:auto!important}
[data-slot='sidebar-inner'] [data-slot='sidebar-content'] > .drag-region{flex:0 0 0px!important}
